<?php declare(strict_types=1);namespace App\Services;use App\Core\Database;use App\Models\User;final class AuthService{public function __construct(private Database $db){}public function attempt(string $email,string $password):bool{$u=(new User($this->db))->findByEmail($email);if(!$u||!password_verify($password,$u['password_hash']))return false;session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['role']=$u['role'];return true;}public function user():?array{return isset($_SESSION['user_id'])?(new User($this->db))->find((int)$_SESSION['user_id']):null;}public function logout():void{$_SESSION=[];session_destroy();}}
